// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

/**
 * Phase B review round (F2, adopted from the reviewer's scratch test): a broad evidence change (the cache's evidence
 * epoch) that lands between a lookup's {@code Revalidate} and its re-stamp must not be served as revalidated: the
 * version is withdrawn from lookup. It kills the removal of the epoch re-check in {@code revalidatable}, which the
 * other tests (that bump the epoch only before the lookup) leave green.
 */
class LmdbPlanCacheRevalidationRaceTest {

	@ParameterizedTest(name = "ranked={0}")
	@ValueSource(booleans = { false, true })
	void aBroadEvidenceChangeBetweenTheReplayAndTheRestampIsNotServedAsRevalidated(boolean ranked) {
		LmdbPlanCacheRevalidationTest outer = new LmdbPlanCacheRevalidationTest();
		try (LmdbPlanCacheRevalidationTest.Harness harness = outer.new Harness()) {
			harness.publish(LmdbPlanCacheRevalidationTest.learned(17L, 3L), ranked);
			long epochBefore = harness.decisions().statistics().globalEvidenceEpoch();
			LmdbPlanCacheRevalidationTest.StubValidator validator = new LmdbPlanCacheRevalidationTest.StubValidator(
					LmdbPlanningReadLog.Verdict.IDENTICAL);
			// While the request replays (no cache lock held), a broad evidence change withdraws every version.
			validator.during = () -> harness.decisions()
					.markEvidenceChanged(new LmdbPlanDecisionCache.EvidenceChange(
							new LmdbPlanDecisionCache.EvidenceDependency(LmdbPlanDecisionCache.EvidenceKind.LEO,
									"global", 1L),
							false, true));

			LmdbPipelinePlanCache.Result result = harness.lookup(LmdbPlanCacheRevalidationTest.learned(17L, 30L),
					ranked, validator);

			String reason = result.plan().getStringMetricPlanned("optimizer.planCacheRefreshReason");
			assertAll(
					() -> assertEquals(1, validator.calls.get(), "COVERAGE_PREREQUISITE: the variant was replayed"),
					() -> assertEquals(epochBefore + 1L, harness.decisions().statistics().globalEvidenceEpoch(),
							"COVERAGE_PREREQUISITE: the epoch moved during the replay"),
					() -> assertFalse(reason != null && reason.startsWith("revalidated"),
							"a version withdrawn during the replay is not served as revalidated: " + reason),
					() -> assertEquals(0L, harness.revalidation().restamps(), "nothing is re-stamped"));
		}
	}
}
